/* ── DATE / TIME ─────────────────────────────────────────── */
function formatDate(date) {
  const days   = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  return `${days[date.getDay()]}, ${months[date.getMonth()]} ${date.getDate()}`;
}
function formatTime(date) {
  let h = date.getHours(); const m = String(date.getMinutes()).padStart(2,'0');
  const ap = h >= 12 ? 'pm' : 'am'; h = h % 12 || 12;
  return `${h}:${m} ${ap}`;
}
function formatTimestamp(ts) {
  if (!ts) return '';
  const d = new Date(ts);
  return `${formatDate(d).split(',')[1].trim()} ${formatTime(d)}`;
}
function todayStr() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}
function formatDisplayDate(str) {
  if (!str) return '';
  const [,m,d] = str.split('-').map(Number);
  return `${'Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec'.split(' ')[m-1]} ${d}`;
}
function updateClock() {
  const now = new Date();
  const dt = document.getElementById('app-date-text');
  const tm = document.getElementById('app-time');
  if (dt) dt.textContent = formatDate(now);
  if (tm) tm.textContent = formatTime(now);
}
updateClock();
setInterval(updateClock, 1000);

