/* ── FIRE ANIMATION HELPER ───────────────────────────────── */

/*
  Colour strategy: the Lottie flame is naturally orange/amber.
  We shift it using CSS filter chains — hue-rotate pivots the hue wheel,
  saturate keeps vibrancy, brightness fine-tunes lightness.
  
  Hue wheel from orange base (~30°):
    Grey   (0)  : grayscale(1)
    Yellow (1–5) : hue-rotate(-25deg)  orange → yellow
    Orange (6–10): hue-rotate(0deg)    native flame colour
    Red   (11–15): hue-rotate(25deg)   orange → red
    Purple(16–20): hue-rotate(130deg)  orange → purple
*/
function getFlameFilter(count) {
  if (count === 0) return 'grayscale(1) opacity(0.4)';

  // Orange flame is ~30deg on the hue wheel.
  // To reach purple (300deg) without crossing green (90-180deg),
  // we go NEGATIVE (backwards through red/magenta) to -60deg = 300deg.
  //   Yellow : hue-rotate(-25deg)  orange->yellow
  //   Orange : hue-rotate(0deg)    native
  //   Red    : hue-rotate(-30deg)  orange->red
  //   Purple : hue-rotate(-120deg) red->magenta->purple  (avoids green entirely)
  let hue, sat, bright;
  if (count <= 5) {
    const t = (count - 1) / 4;    // 0->1
    hue    = -25 + t * 25;        // -25deg -> 0deg  (yellow -> orange)
    sat    = 1.5 - t * 0.2;
    bright = 1.3 - t * 0.1;
  } else if (count <= 10) {
    const t = (count - 5) / 5;    // 0->1
    hue    = 0 - t * 30;          // 0deg -> -30deg  (orange -> red)
    sat    = 1.3 + t * 0.2;
    bright = 1.1 - t * 0.1;
  } else if (count <= 15) {
    const t = (count - 10) / 5;   // 0->1
    hue    = -30;                  // hold at red
    sat    = 1.5 + t * 0.2;
    bright = 1.0 - t * 0.05;
  } else {
    const t = (count - 15) / 5;   // 0->1
    hue    = -30 - t * 90;        // -30deg -> -120deg  (red -> purple, no green)
    sat    = 1.7 + t * 0.5;
    bright = 0.95;
  }

  return `hue-rotate(${hue.toFixed(1)}deg) saturate(${sat.toFixed(2)}) brightness(${bright.toFixed(2)})`;
}

function updateFireIcon(streakCount) {
  const badgeEl  = document.getElementById('lottie-badge-fire');
  const heroEl   = document.getElementById('lottie-hero-fire');
  const heroNum  = document.getElementById('hero-streak-number');
  const heroMax  = document.getElementById('hero-stat-max');
  const heroStart= document.getElementById('hero-stat-start');

  const count = Math.min(streakCount, 20);

  // Speed is constant at 1 regardless of streak
  if (typeof badgeFireAnim !== 'undefined' && badgeFireAnim) badgeFireAnim.setSpeed(1);
  if (typeof heroFireAnim  !== 'undefined' && heroFireAnim)  heroFireAnim.setSpeed(1);

  const flameFilter = getFlameFilter(count);

  // Glow colour for drop-shadow — complements the flame colour
  const glowColors = [
    'transparent',
    '#FFE033','#FFD420','#FFC300','#FFB300','#FFA000',
    '#FF8C00','#FF7400','#FF5E00','#FF4500','#FF2D00',
    '#FF1A00','#F20000','#D80000','#C00000','#A80000',
    '#9B2090','#8B18A0','#7B10B0','#6A08C0','#5900D0',
  ];

  // Badge: scales with streak, 0.5 at streak 1 → 1.2 at streak 20
  if (badgeEl) {
    const badgeScale = count === 0 ? 0.4 : 0.50 + (count / 20) * 0.70;
    badgeEl.style.transform = `scale(${badgeScale.toFixed(3)})`;
    badgeEl.style.filter = flameFilter;
  }

  // Hero: base container 70×80px
  // Scale: 0.5 at streak 1, 2.25 at streak 20  (50% bigger than previous 1.50 max)
  if (heroEl) {
    const heroScale = count === 0
      ? 0
      : 0.50 + (count / 20) * 1.75;  // 0.50 → 2.25

    heroEl.style.transform = `translateX(-50%) scale(${heroScale.toFixed(3)})`;
    heroEl.style.opacity   = count === 0 ? '0' : '1';

    if (count === 0) {
      heroEl.style.filter = 'none';
    } else {
      const glow = glowColors[count];
      const glowSize = 6 + count * 1.5;
      // Apply colour-shift filter + glow together
      heroEl.style.filter = `${flameFilter} drop-shadow(0 0 ${glowSize}px ${glow}) drop-shadow(0 0 ${glowSize * 1.8}px ${glow})`;
    }

    // Embers — colour matches current streak stage
    const embersContainer = document.getElementById('embers-container');
    if (embersContainer) {
      embersContainer.innerHTML = '';
      const numEmbers = count < 5 ? 0 : Math.floor(count * 1.5);
      for (let i = 0; i < numEmbers; i++) {
        const ember = document.createElement('div');
        ember.className = 'ember';
        ember.style.left = `${Math.random() * 100}%`;
        ember.style.setProperty('--ember-x', `${(Math.random() - 0.5) * 60}px`);
        ember.style.setProperty('--ember-y', `-${80 + Math.random() * 80}px`);
        ember.style.animationDuration = `${1 + Math.random() * 2}s`;
        ember.style.animationDelay    = `${Math.random() * 2}s`;
        ember.style.background = glowColors[Math.max(1, count - Math.floor(Math.random() * 4))];
        const size = 3 + Math.random() * 4;
        ember.style.width  = `${size}px`;
        ember.style.height = `${size}px`;
        embersContainer.appendChild(ember);
      }
    }
  }

  if (heroNum) heroNum.textContent = streakCount;
  if (heroMax) heroMax.textContent = streak.maxCount || streakCount;
  if (heroStart) {
    if (streakCount === 0 || !streak.startDate) {
      heroStart.textContent = '--';
    } else {
      const parts = streak.startDate.split('-');
      if (parts.length === 3) {
        const d = new Date(parts[0], parts[1]-1, parts[2]);
        const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
        heroStart.textContent = `${months[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()}`;
      } else {
        heroStart.textContent = streak.startDate;
      }
    }
  }
}

/* ── CLOUD HELPERS ───────────────────────────────────────── */
async function saveTask(task) {
  setSyncStatus('saving');
  try {
    await tasksRef.doc(task.id).set(task);
    setSyncStatus(themeMode==='auto'?'synced':'manual');
  } catch {
    setSyncStatus('offline');
    showToast({ type:'error', message:'Save failed — check your connection.', duration:5000 });
  }
}
async function deleteTaskCloud(id) {
  setSyncStatus('saving');
  try {
    await tasksRef.doc(id).delete();
    setSyncStatus(themeMode==='auto'?'synced':'manual');
  } catch {
    setSyncStatus('offline');
    showToast({ type:'error', message:'Delete failed — check your connection.', duration:5000 });
  }
}
async function saveMeta() {
  try { await metaRef.set({ totalXP, streak }, { merge: true }); } catch {}
}

/* ── REALTIME LISTENER ───────────────────────────────────── */
function startSync() {
  firestoreUnsubTasks = tasksRef.onSnapshot(snap => {
    tasks = [];
    snap.forEach(doc => {
      const t = doc.data();
      if (!pendingDeletes.has(t.id)) tasks.push(t); // skip tasks pending undo-delete
    });
    carryOver();
    renderTasks();
    if (window.electronAPI && window.electronAPI.sendTasks) {
      window.electronAPI.sendTasks(tasks);
    }
    setSyncStatus(themeMode==='auto'?'synced':'manual');
  }, () => {
    setSyncStatus('offline');
    showToast({ type:'error', message:'Lost connection to cloud — changes may not save.', duration:6000 });
  });

  if (window.electronAPI && window.electronAPI.onToggleTask) {
    window.electronAPI.onToggleTask(async (taskId, newDone) => {
      const task = tasks.find(t => t.id === taskId);
      if (!task) return;
      
      // If toggling ON from electron but subtasks incomplete, reject it
      if (newDone && Array.isArray(task.subItems) && task.subItems.length > 0) {
        if (!task.subItems.every(s => s.done)) {
          showToast({ type: 'error', message: 'Complete all subtasks first!', duration: 3000 });
          return;
        }
      }
      
      if (task.done !== newDone) {
        // use the standard toggleTask so we get XP + animations
        toggleTask(taskId, null);
      }
    });
  }

  firestoreUnsubMeta = metaRef.onSnapshot(doc => {
    if (doc.exists) {
      const d = doc.data();
      totalXP = d.totalXP || 0;
      streak  = d.streak  || { count: 0, lastDate: '', maxCount: 0, startDate: '' };
      streak.maxCount = streak.maxCount || streak.count;
      
      if (streak.count > 0 && !streak.startDate) {
        const dd = new Date(streak.lastDate || todayStr());
        dd.setDate(dd.getDate() - (streak.count - 1));
        streak.startDate = `${dd.getFullYear()}-${String(dd.getMonth()+1).padStart(2,'0')}-${String(dd.getDate()).padStart(2,'0')}`;
      }

      // ── Streak staleness check: reset if last active day wasn't yesterday or today ──
      if (streak.lastDate) {
        const yest = (() => {
          const dd = new Date(); dd.setDate(dd.getDate() - 1);
          return `${dd.getFullYear()}-${String(dd.getMonth()+1).padStart(2,'0')}-${String(dd.getDate()).padStart(2,'0')}`;
        })();
        if (streak.lastDate < yest) {
          streak.count = 0;        // missed a day — reset count display
          // Note: don't overwrite lastDate so re-opening tomorrow still resets correctly
        }
      }

      document.getElementById('streak-count').textContent = streak.count;
      updateFireIcon(streak.count);
      renderProgress();
    }
  });
}
/* ─────────────────────────────────────────────────────────
   AUTH FLOW
   ─────────────────────────────────────────────────────────*/
let firestoreUnsubTasks = null;
let firestoreUnsubMeta  = null;

function showAuthOverlay(show) {
  const overlay = document.getElementById('auth-overlay');
  if (overlay) overlay.style.display = show ? 'flex' : 'none';
}

function showApp(user) {
  showAuthOverlay(false);
  document.getElementById('auth-error').textContent = '';

  // Show user chip
  const chip   = document.getElementById('user-chip');
  const avatar = document.getElementById('user-avatar');
  if (chip) chip.style.display = 'flex';
  if (avatar) {
    if (user.photoURL) {
      avatar.src   = user.photoURL;
      avatar.style.display = 'block';
    } else {
      // Show initial letter as fallback
      avatar.style.display = 'none';
      chip.querySelector('.user-avatar') && (chip.querySelector('.user-initial') || (() => {
        const span = document.createElement('span');
        span.className = 'user-initial';
        span.textContent = (user.displayName || user.email || '?')[0].toUpperCase();
        chip.insertBefore(span, chip.firstChild);
      })());
    }
  }
}

function hideApp() {
  showAuthOverlay(true);
  const chip = document.getElementById('user-chip');
  if (chip) chip.style.display = 'none';
  // Unsubscribe Firestore listeners
  if (firestoreUnsubTasks) { firestoreUnsubTasks(); firestoreUnsubTasks = null; }
  if (firestoreUnsubMeta)  { firestoreUnsubMeta();  firestoreUnsubMeta  = null; }
  // Reset state
  // FIX 9: Reset ALL user-specific state on sign-out — streak, XP, tasks
  // Each user's streak is stored under /users/{uid}/meta/stats in Firestore
  // so it is fully isolated per-user. No shared state.
  tasks   = [];
  totalXP = 0;
  streak  = { count: 0, lastDate: '', maxCount: 0, startDate: '' };
  document.getElementById('streak-count').textContent = '0';
  updateFireIcon(0);
  renderTasks();
  renderProgress();
}

