// Email sign-in / sign-up
const handleAuth = async (isSignUp) => {
  const email    = document.getElementById('auth-email').value.trim();
  const password = document.getElementById('auth-password').value;
  const errEl    = document.getElementById('auth-error');
  errEl.textContent = '';
  if (!email || !password) { errEl.textContent = 'Please enter email and password.'; return; }
  try {
    if (isSignUp) {
      await auth.createUserWithEmailAndPassword(email, password);
    } else {
      await auth.signInWithEmailAndPassword(email, password);
    }
  } catch (err) {
    errEl.textContent = err.message.replace('Firebase: ', '');
  }
};

document.getElementById('auth-signin-btn').addEventListener('click', () => handleAuth(false));
document.getElementById('auth-signup-btn').addEventListener('click', () => handleAuth(true));

