function buildDayMap() {
  const map = {};
  tasks.forEach(t => {
    // FIX 5: Don't credit the carried-from date — only count tasks on their actual date
    if (t.originalDate && t.originalDate !== t.date) {
      if (!map[t.originalDate]) map[t.originalDate] = { total: 0, done: 0, tasks: [], hasCarryOverFrom: false };
      map[t.originalDate].hasCarryOverFrom = true;
    }
    if (!t.date) return;
    if (!map[t.date]) map[t.date] = { total: 0, done: 0, tasks: [], hasCarryOverFrom: false };
    map[t.date].total++;
    if (t.done) map[t.date].done++;
    map[t.date].tasks.push(t);
  });
  return map;
}

function calDateStr(y,m,d) {
  return `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
}

function renderCalendar() {
  const today   = todayStr();
  const dayMap  = buildDayMap();
  const MONTHS  = ['January','February','March','April','May','June','July','August','September','October','November','December'];

  document.getElementById('cal-month-title').textContent = `${MONTHS[calMonth]} ${calYear}`;

  // Stats
  const prefix   = `${calYear}-${String(calMonth+1).padStart(2,'0')}`;
  const mDays    = Object.keys(dayMap).filter(k=>k.startsWith(prefix));
  const perfect  = mDays.filter(k=>dayMap[k].done>0&&dayMap[k].done===dayMap[k].total).length;
  const totDone  = mDays.reduce((s,k)=>s+dayMap[k].done,0);
  const active   = mDays.filter(k=>dayMap[k].done>0).length;

  document.getElementById('cal-stats').innerHTML = `
    <div class="cal-stat-chip"><span class="cal-stat-chip-num">${perfect}</span><span class="cal-stat-chip-lbl">perfect days</span></div>
    <div class="cal-stat-chip"><span class="cal-stat-chip-num">${totDone}</span><span class="cal-stat-chip-lbl">tasks done</span></div>
    <div class="cal-stat-chip"><span class="cal-stat-chip-num">${active}</span><span class="cal-stat-chip-lbl">active days</span></div>`;

  // Grid
  const grid = document.getElementById('cal-grid');
  grid.innerHTML = '';
  const firstDay    = new Date(calYear, calMonth, 1).getDay();
  const daysInMonth = new Date(calYear, calMonth+1, 0).getDate();

  // Find streak runs (2+ consecutive perfect days)
  const streakSet = new Set();
  let run = [];
  for (let d=1; d<=daysInMonth; d++) {
    const ds   = calDateStr(calYear,calMonth,d);
    const info = dayMap[ds];
    if (info && info.done>0 && info.done===info.total) { run.push(ds); }
    else { if (run.length>=2) run.forEach(s=>streakSet.add(s)); run=[]; }
  }
  if (run.length>=2) run.forEach(s=>streakSet.add(s));

  // Empty leading cells
  for (let i=0;i<firstDay;i++) {
    const e=document.createElement('div'); e.className='cal-day cal-day-empty'; grid.appendChild(e);
  }

  for (let d=1; d<=daysInMonth; d++) {
    const ds   = calDateStr(calYear,calMonth,d);
    const info = dayMap[ds];
    const cell = document.createElement('div');
    cell.className='cal-day'; cell.setAttribute('data-date',ds);

    const isToday   = ds===today;
    const isFuture  = ds>today;
    const isPerfect = info&&info.done>0&&info.done===info.total&&!info.hasCarryOverFrom;
    const isPartial = info&&( (info.done>0&&info.done<info.total) || info.hasCarryOverFrom );
    const isMissed  = info&&info.total>0&&info.done===0&&!isFuture&&!info.hasCarryOverFrom;
    const inStreak  = streakSet.has(ds);

    if (isFuture)  cell.classList.add('cal-day-future');
    if (isToday)   cell.classList.add('cal-day-today');
    
    // Calculate completion percentage for heatmap style
    let completionPct = 0;
    if (info && info.total > 0 && !info.hasCarryOverFrom && !isFuture) {
      completionPct = info.done / info.total;
    }

    // Set a custom CSS variable for the background opacity
    cell.style.setProperty('--heatmap-opacity', completionPct.toFixed(2));
    if (completionPct > 0) cell.classList.add('cal-day-active');
    if (completionPct === 1) cell.classList.add('cal-day-perfect-heatmap');

    const showDot = (isPartial||isMissed)&&!isPerfect;
    cell.innerHTML = `<span class="cal-day-num">${d}</span>${showDot?'<span class="cal-day-dot"></span>':''}`;

    if (!isFuture) cell.addEventListener('click',()=>showDayDetail(ds));
    grid.appendChild(cell);
  }
}

function showDayDetail(ds) {
  document.querySelectorAll('.cal-day').forEach(c=>c.classList.remove('cal-day-selected'));
  const clicked = document.querySelector(`[data-date="${ds}"]`);
  if (clicked) clicked.classList.add('cal-day-selected');

  const dayMap = buildDayMap();
  const info   = dayMap[ds];
  const detail = document.getElementById('cal-detail');
  const months = 'Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec'.split(' ');
  const [,m,d] = ds.split('-').map(Number);

  document.getElementById('cal-detail-title').textContent = `${months[m-1]} ${d}, ${ds.split('-')[0]}`;

  const tasksEl = document.getElementById('cal-detail-tasks');
  if (!info||!info.tasks.length) {
    tasksEl.innerHTML='<p class="cal-empty-day">No tasks recorded.</p>';
  } else {
    const sorted = [...info.tasks].sort((a,b)=>a.done===b.done?0:a.done?1:-1);
    tasksEl.innerHTML = sorted.map(t=>`
      <div class="cal-detail-task">
        <div style="display:flex; align-items:center; width:100%;">
          <div class="cal-detail-check ${t.done?'done':''}">
            ${t.done?`<svg width="8" height="8" viewBox="0 0 8 8" fill="none"><path d="M1 4l2 2 4-4" stroke="var(--page-bg)" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg>`:''}
          </div>
          <span class="cal-detail-task-name ${t.done?'done':''}">${escHtml(t.name)}</span>
          <span class="badge badge-${t.priority}" style="font-size:10px; margin-left:auto;">${t.priority.charAt(0).toUpperCase()+t.priority.slice(1)}</span>
        </div>
        ${t.subItems && t.subItems.length > 0 ? `
          <div style="display:flex; flex-direction:column; gap:4px; margin-top:8px; margin-left:24px;">
            ${t.subItems.map(s => `
              <div style="display:flex; align-items:center; gap:6px; font-size:12px; color:var(--ink-3);">
                <div style="width:12px; height:12px; border-radius:50%; border:1px solid var(--border-mid); display:flex; align-items:center; justify-content:center; background:${s.done?'var(--accent)':'transparent'}; border-color:${s.done?'var(--accent)':'var(--border-mid)'}">
                  ${s.done ? `<svg width="6" height="6" viewBox="0 0 8 8" fill="none"><path d="M1 4l2 2 4-4" stroke="var(--page-bg)" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/></svg>` : ''}
                </div>
                <span style="text-decoration:${s.done?'line-through':'none'}; opacity:${s.done?'0.6':'1'};">${escHtml(s.name)}</span>
              </div>
            `).join('')}
          </div>
        ` : ''}
      </div>`).join('');
  }
  detail.style.display='block';
  detail.scrollIntoView({behavior:'smooth',block:'nearest'});
}

/* ── SUMMARY ─────────────────────────────────────────────── */
function showSummary(done, total) {
  const today  = todayStr();
  const earned = tasks.filter(t=>t.date===today&&t.done).reduce((s,t)=>s+xpFor(t.priority),0);
  let bonus=0;
  if (done===total&&total>0) { bonus=50; totalXP+=bonus; saveMeta(); }
  const msgs=['You showed up and got it done.','Consistency is a superpower.','Another day in the books.','Momentum is everything.','Your future self says thank you.'];
  document.getElementById('summary-title').textContent  = done===total?'Perfect day!':`${done} of ${total} done`;
  document.getElementById('summary-sub').textContent    = msgs[Math.floor(Math.random()*msgs.length)];
  document.getElementById('summary-done').textContent   = done;
  document.getElementById('summary-xp').textContent     = earned+(bonus?` +${bonus}`:'');
  document.getElementById('summary-streak').textContent = streak.count;
  document.getElementById('summary-overlay').style.display='flex';
}

document.getElementById('plan-tomorrow-btn').addEventListener('click',()=>{
  document.getElementById('summary-overlay').style.display='none';
  switchTab('upcoming');
  setTimeout(()=>{
    openAddPanel();
    sel.schedule='date'; setChips('schedule-chips','date');
    dateInput.style.display='block';
    const t=new Date(); t.setDate(t.getDate()+1);
    dateInput.value=t.toISOString().split('T')[0]; dateInput.min=todayStr();
  },300);
});

document.getElementById('dismiss-summary-btn').addEventListener('click',()=>{
  document.getElementById('summary-overlay').style.display='none';
});

/* ─────────────────────────────────────────────────────────
   DRAG-AND-DROP REORDER (Today tab)
   Allows dragging task cards to reorder within or across
   priority groups. Priority is updated when a card is
   dropped under a different priority section header.
   ───────────────────────────────────────────────────────── */

let dragState = null; // { id, element }

function clearDropIndicators() {
  document.querySelectorAll('.drop-indicator').forEach(el => el.remove());
  document.querySelectorAll('[data-drop-target]').forEach(el => delete el.dataset.dropTarget);
}

function initTodayDragDrop() {
  const todayList = document.getElementById('today-list');
  if (!todayList) return;

  todayList.querySelectorAll('.task-card').forEach(card => {
    const taskId = card.getAttribute('data-id');
    const handle = card.querySelector('.drag-handle');
    if (!handle) return;

    // ── Mouse drag (desktop) ──
    handle.addEventListener('mousedown', () => { card.draggable = true; });
    handle.addEventListener('mouseup',   () => { setTimeout(() => { card.draggable = false; }, 50); });

    card.addEventListener('dragstart', e => {
      if (!card.draggable) { e.preventDefault(); return; }
      dragState = { id: taskId, element: card };
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', taskId);
      setTimeout(() => card.classList.add('dragging'), 0);
      document.body.classList.add('drag-active');
    });
    card.addEventListener('dragend', () => {
      card.classList.remove('dragging');
      card.draggable = false;
      document.body.classList.remove('drag-active');
      clearDropIndicators();
      dragState = null;
    });
    card.addEventListener('dragover', e => {
      if (!dragState || dragState.id === taskId) return;
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      clearDropIndicators();
      const rect = card.getBoundingClientRect();
      const isAbove = e.clientY < rect.top + rect.height / 2;
      const indicator = document.createElement('div');
      indicator.className = 'drop-indicator';
      card.dataset.dropTarget = isAbove ? 'before' : 'after';
      isAbove ? todayList.insertBefore(indicator, card) : todayList.insertBefore(indicator, card.nextSibling);
    });
    card.addEventListener('drop', e => {
      e.preventDefault();
      if (!dragState || dragState.id === taskId) return;
      const position = card.dataset.dropTarget || 'after';
      clearDropIndicators();
      card.draggable = false;
      performTodayReorder(dragState.id, taskId, position === 'before');
      dragState = null;
    });

    // ── Touch drag (mobile) ──
    let touchDragId = null;
    let touchClone  = null;
    let touchOffsetY = 0;

    handle.addEventListener('touchstart', e => {
      e.stopPropagation();
      touchDragId = taskId;
      dragState   = { id: taskId, element: card };
      card.classList.add('dragging');
      document.body.classList.add('drag-active');

      // Create a visual clone that follows the finger
      touchClone = card.cloneNode(true);
      touchClone.classList.add('touch-drag-clone');
      const rect = card.getBoundingClientRect();
      touchOffsetY = e.touches[0].clientY - rect.top;
      touchClone.style.cssText = `
        position:fixed; left:${rect.left}px; top:${rect.top}px;
        width:${rect.width}px; z-index:999; pointer-events:none;
        opacity:.88; box-shadow:0 12px 36px var(--shadow-strong);
        transform:scale(1.02); transition:none;
      `;
      document.body.appendChild(touchClone);
    }, { passive: true });

    handle.addEventListener('touchmove', e => {
      if (!touchDragId || touchDragId !== taskId) return;
      e.preventDefault();
      const touch = e.touches[0];
      if (touchClone) {
        touchClone.style.top = (touch.clientY - touchOffsetY) + 'px';
      }
      clearDropIndicators();
      // Find card under finger
      touchClone.style.display = 'none';
      const el = document.elementFromPoint(touch.clientX, touch.clientY);
      touchClone.style.display = '';
      const targetCard = el ? el.closest('.task-card') : null;
      if (targetCard && targetCard !== card) {
        const rect = targetCard.getBoundingClientRect();
        const isAbove = touch.clientY < rect.top + rect.height / 2;
        const indicator = document.createElement('div');
        indicator.className = 'drop-indicator';
        targetCard.dataset.dropTarget = isAbove ? 'before' : 'after';
        isAbove ? todayList.insertBefore(indicator, targetCard) : todayList.insertBefore(indicator, targetCard.nextSibling);
      }
    }, { passive: false });

    handle.addEventListener('touchend', e => {
      if (!touchDragId || touchDragId !== taskId) return;
      card.classList.remove('dragging');
      document.body.classList.remove('drag-active');
      if (touchClone) { touchClone.remove(); touchClone = null; }

      const touch = e.changedTouches[0];
      // Find drop target
      const el = document.elementFromPoint(touch.clientX, touch.clientY);
      const targetCard = el ? el.closest('.task-card') : null;
      clearDropIndicators();

      if (targetCard && targetCard !== card) {
        const tId = targetCard.getAttribute('data-id');
        const rect = targetCard.getBoundingClientRect();
        const insertBefore = touch.clientY < rect.top + rect.height / 2;
        performTodayReorder(taskId, tId, insertBefore);
      }
      touchDragId = null;
      dragState   = null;
    }, { passive: true });
  });
}

async function performTodayReorder(draggedId, targetId, insertBefore) {
  const today       = todayStr();
  const draggedTask = tasks.find(t => t.id === draggedId);
  const targetTask  = tasks.find(t => t.id === targetId);
  if (!draggedTask || !targetTask) return;

  const oldPriority = draggedTask.priority;
  const newPriority = targetTask.priority;

  // Build the currently-sorted today list (same order as rendered)
  const todayTasks = tasks
    .filter(t => t.date === today)
    .sort((a, b) => {
      const pd = priorityOrder(a.priority) - priorityOrder(b.priority);
      if (pd !== 0) return pd;
      return (a.sortOrder || a.created || 0) - (b.sortOrder || b.created || 0);
    });

  // Remove dragged task from list, update its priority
  draggedTask.priority = newPriority;
  const reordered = todayTasks.filter(t => t.id !== draggedId);

  // Insert at target position
  const targetIdx = reordered.findIndex(t => t.id === targetId);
  if (targetIdx === -1) return;
  reordered.splice(insertBefore ? targetIdx : targetIdx + 1, 0, draggedTask);

  // Assign fresh sortOrders (spacing of 1000 allows future inserts without renumbering)
  const changed = [];
  reordered.forEach((t, i) => {
    const newOrder = (i + 1) * 1000;
    if (t.sortOrder !== newOrder || t.id === draggedId) {
      t.sortOrder = newOrder;
      changed.push(t);
    }
  });

  // Optimistically re-render before cloud saves
  renderTasks();

  // Notify on priority change
  if (oldPriority !== newPriority) {
    const label = newPriority.charAt(0).toUpperCase() + newPriority.slice(1);
    showToast({ type: 'info', message: `Priority changed to ${label}`, duration: 2500 });
  }

  // Persist only the changed tasks
  await Promise.all(changed.map(t => saveTask(t)));
}

/* ─────────────────────────────────────────────────────────

   TOAST NOTIFICATION SYSTEM
   showToast({ type, message, duration, undoFn })
   types: 'success' | 'error' | 'warning' | 'info'
   ───────────────────────────────────────────────────────── */
const toastContainer = document.getElementById('toast-container');

const TOAST_ICONS = {
  success: `<svg width="13" height="13" viewBox="0 0 13 13" fill="none"><path d="M2 6.5l3.5 3.5 5.5-6" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>`,
  error:   `<svg width="13" height="13" viewBox="0 0 13 13" fill="none"><line x1="2" y1="2" x2="11" y2="11" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><line x1="11" y1="2" x2="2" y2="11" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>`,
  warning: `<svg width="13" height="13" viewBox="0 0 13 13" fill="none"><path d="M6.5 2v5M6.5 9v1.2" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"/></svg>`,
  info:    `<svg width="13" height="13" viewBox="0 0 13 13" fill="none"><circle cx="6.5" cy="6.5" r="5" stroke="currentColor" stroke-width="1.4"/><path d="M6.5 6v3.5M6.5 4v.5" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg>`,
};

function showToast({ type = 'info', message, duration = 4000, undoFn = null }) {
  const toast = document.createElement('div');
  toast.className = `toast toast-${type}`;

  // Build inner structure
  const iconEl    = document.createElement('div');
  iconEl.className = 'toast-icon';
  iconEl.innerHTML = TOAST_ICONS[type];

  const msgEl    = document.createElement('span');
  msgEl.className = 'toast-msg';
  msgEl.textContent = message;   // textContent = safe, no XSS

  const closeEl  = document.createElement('button');
  closeEl.className    = 'toast-close-btn';
  closeEl.setAttribute('aria-label', 'Dismiss');
  closeEl.innerHTML    = `<svg width="12" height="12" viewBox="0 0 12 12" fill="none"><line x1="1" y1="1" x2="11" y2="11" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/><line x1="11" y1="1" x2="1" y2="11" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>`;

  const progressEl = document.createElement('div');
  progressEl.className = 'toast-progress';

  toast.appendChild(iconEl);
  toast.appendChild(msgEl);

  let undoEl = null;
  if (undoFn) {
    undoEl           = document.createElement('button');
    undoEl.className  = 'toast-undo-btn';
    undoEl.textContent = 'Undo';
    toast.appendChild(undoEl);
  }

  toast.appendChild(closeEl);
  toast.appendChild(progressEl);

  // ── Dismiss logic with hover-pause ──
  let dismissed  = false;
  let remaining  = duration;
  let startStamp = Date.now();
  let autoTimer;

  function dismiss() {
    if (dismissed) return;
    dismissed = true;
    clearTimeout(autoTimer);
    toast.classList.add('toast-out');
    setTimeout(() => toast.remove(), 280);
  }

  function startTimer(ms) {
    startStamp = Date.now();
    autoTimer  = setTimeout(dismiss, ms);
  }

  closeEl.addEventListener('click', dismiss);

  if (undoEl) {
    undoEl.addEventListener('click', () => { undoFn(); dismiss(); });
  }

  // Pause progress bar & timer on hover
  toast.addEventListener('mouseenter', () => {
    clearTimeout(autoTimer);
    remaining = Math.max(0, remaining - (Date.now() - startStamp));
    progressEl.style.animationPlayState = 'paused';
  });
  toast.addEventListener('mouseleave', () => {
    progressEl.style.animationPlayState = 'running';
    startTimer(remaining);
  });

  toastContainer.appendChild(toast);

  // Start progress bar animation (after mount so transition triggers)
  requestAnimationFrame(() => {
    progressEl.style.animation = `toast-progress-shrink ${duration}ms linear forwards`;
  });

  startTimer(duration);
  return dismiss; // caller can forcibly dismiss if needed
}

/* ── UTILITY ─────────────────────────────────────────────── */
function escHtml(s) {
  return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}


/* ═══════════════════════════════════════════════════════════
   PLAN YOUR DAY — Morning Ritual  (additive module)
   Hooks into existing: addTask(), saveMeta(), showXPPop(),
   switchTab(), todayStr(), xpFor(), totalXP, showToast()
   ═══════════════════════════════════════════════════════════ */
(function PlanYourDay() {
  'use strict';

  const PLANNING_XP  = 25;
  const PYD_DONE_KEY = () => `pyd_done_${todayStr()}`;

  /* Encouragement copy */
  const ENCOURAGE = [
    'A start is a start.',
    'Two tasks — building momentum.',
    'Three! The day is taking shape.',
    'Four tasks — solid foundation.',
    'Five tasks. That\'s a full day.',
    'Six — you mean business.',
    'Seven tasks — on fire 🔥',
  ];
  const encourage = n => n <= ENCOURAGE.length ? ENCOURAGE[n-1] : `${n} tasks — let\'s go!`;

  /* Greeting */
  const greeting = () => {
    const h = new Date().getHours();
    if (h >= 5  && h < 12) return 'Good morning.';
    if (h >= 12 && h < 17) return 'Good afternoon.';
    if (h >= 17 && h < 21) return 'Good evening.';
    return 'Working late?';
  };
  const daySubtitle = () => {
    const d = new Date();
    const DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
    const MOS  = ['January','February','March','April','May','June','July','August','September','October','November','December'];
    return `${DAYS[d.getDay()]}, ${MOS[d.getMonth()]} ${d.getDate()} — let\'s make it count.`;
  };

  /* Module state */
  let dumped      = [];   // [{name, id}]
  let prioritised = [];   // [{name, id, priority}]
  let cardIdx     = 0;

  /* Element refs */
  const overlay      = document.getElementById('pyd-overlay');
  const sDump        = document.getElementById('pyd-screen-dump');
  const sPrio        = document.getElementById('pyd-screen-prioritise');
  const sCommit      = document.getElementById('pyd-screen-commit');
  const greetEl      = document.getElementById('pyd-greeting');
  const dayEl        = document.getElementById('pyd-day-text');
  const rapidInput   = document.getElementById('pyd-rapid-input');
  const rapidAddBtn  = document.getElementById('pyd-rapid-add-btn');
  const dumpList     = document.getElementById('pyd-dump-list');
  const countEl      = document.getElementById('pyd-task-count');
  const counterWrap  = document.getElementById('pyd-counter');
  const encourageEl  = document.getElementById('pyd-encourage');
  const nextBtn      = document.getElementById('pyd-next-btn');
  const nextLabel    = document.getElementById('pyd-next-label');
  const skipBtn      = document.getElementById('pyd-skip-btn');
  const backBtn      = document.getElementById('pyd-back-btn');
  const cardStack    = document.getElementById('pyd-card-stack');
  const dotsWrap     = document.getElementById('pyd-progress-dots');
  const stepLabel    = document.getElementById('pyd-step-label');
  const labelLow     = document.getElementById('pyd-label-low');
  const labelHigh    = document.getElementById('pyd-label-high');

  /* Screen management */
  const showScreen = name => {
    sDump.style.display   = name === 'dump'   ? 'flex' : 'none';
    sPrio.style.display   = name === 'prio'   ? 'flex' : 'none';
    sCommit.style.display = name === 'commit' ? 'flex' : 'none';
  };

  /* ── Open ── */
  function openPYD() {
    dumped = []; prioritised = []; cardIdx = 0;
    dumpList.innerHTML = '';
    rapidInput.value   = '';
    countEl.textContent = '0';
    encourageEl.textContent = '';
    encourageEl.style.opacity = '0';
    nextBtn.disabled = true;
    nextLabel.textContent = 'Prioritise tasks →';

    greetEl.textContent = greeting();
    dayEl.textContent   = daySubtitle();

    showScreen('dump');
    overlay.style.display = 'flex';
    overlay.classList.remove('pyd-exit');
    overlay.classList.add('pyd-enter');
    overlay.addEventListener('animationend', () => overlay.classList.remove('pyd-enter'), { once: true });

    document.body.style.overflow = 'hidden';
    // Close calendar if open
    const calWrap = document.getElementById('cal-inline-wrap');
    if (calWrap) calWrap.style.display = 'none';

    setTimeout(() => rapidInput.focus(), 350);
  }

  /* ── Close ── */
  function closePYD(goToToday) {
    overlay.classList.add('pyd-exit');
    overlay.addEventListener('animationend', () => {
      overlay.style.display = 'none';
      overlay.classList.remove('pyd-exit');
      document.body.style.overflow = '';
    }, { once: true });
    if (goToToday) switchTab('today');
  }

  /* ── Rapid entry ── */
  function addDumpTask() {
    const name = rapidInput.value.trim();
    if (!name) {
      rapidInput.classList.remove('pyd-shake');
      void rapidInput.offsetWidth;
      rapidInput.classList.add('pyd-shake');
      return;
    }
    dumped.push({ name, id: `pyd_${Date.now()}_${Math.random().toString(36).slice(2,6)}` });
    renderDump();
    rapidInput.value = '';
    rapidInput.focus();

    countEl.textContent = dumped.length;
    counterWrap.classList.remove('pyd-bump');
    void counterWrap.offsetWidth;
    counterWrap.classList.add('pyd-bump');

    encourageEl.textContent = encourage(dumped.length);
    encourageEl.style.opacity = '1';

    nextBtn.disabled = false;
    nextLabel.textContent = dumped.length === 1
      ? 'Prioritise 1 task →'
      : `Prioritise ${dumped.length} tasks →`;
  }

  function renderDump() {
    const existing = new Map([...dumpList.querySelectorAll('[data-dump-id]')].map(el => [el.dataset.dumpId, el]));
    existing.forEach((el, id) => { if (!dumped.find(t => t.id === id)) el.remove(); });
    dumped.forEach((t, i) => {
      if (!existing.has(t.id)) {
        const item = document.createElement('div');
        item.className = 'pyd-dump-item';
        item.dataset.dumpId = t.id;
        item.innerHTML = `
          <span class="pyd-dump-num">${i + 1}</span>
          <span class="pyd-dump-name">${escHtml(t.name)}</span>
          <button class="pyd-dump-remove" aria-label="Remove">×</button>`;
        item.querySelector('.pyd-dump-remove').addEventListener('click', e => {
          e.stopPropagation();
          dumped = dumped.filter(x => x.id !== t.id);
          item.classList.add('pyd-dump-removing');
          setTimeout(() => { item.remove(); renumberDump(); }, 220);
          countEl.textContent = dumped.length;
          if (!dumped.length) {
            nextBtn.disabled = true;
            nextLabel.textContent = 'Prioritise tasks →';
            encourageEl.style.opacity = '0';
          } else {
            nextLabel.textContent = dumped.length === 1
              ? 'Prioritise 1 task →'
              : `Prioritise ${dumped.length} tasks →`;
          }
        });
        dumpList.appendChild(item);
      }
    });
  }

  function renumberDump() {
    dumpList.querySelectorAll('.pyd-dump-num').forEach((el, i) => { el.textContent = i + 1; });
    countEl.textContent = dumped.length;
  }

  rapidAddBtn.addEventListener('click', addDumpTask);
  rapidInput.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); addDumpTask(); } });
  skipBtn.addEventListener('click', () => { localStorage.setItem(PYD_DONE_KEY(), '1'); closePYD(false); });

  /* ── Go to prioritise screen ── */
  nextBtn.addEventListener('click', () => {
    if (!dumped.length) return;
    prioritised = [];
    cardIdx = 0;
    buildDots();
    buildStack();
    updateStep();
    showScreen('prio');
  });

  backBtn.addEventListener('click', () => showScreen('dump'));

  /* ── Progress dots ── */
  function buildDots() {
    dotsWrap.innerHTML = '';
    dumped.forEach((_, i) => {
      const d = document.createElement('span');
      d.className = 'pyd-dot' + (i === 0 ? ' active' : '');
      dotsWrap.appendChild(d);
    });
  }

  function updateStep() {
    stepLabel.textContent = `${cardIdx + 1} of ${dumped.length}`;
    dotsWrap.querySelectorAll('.pyd-dot').forEach((d, i) => {
      d.classList.toggle('active', i === cardIdx);
      d.classList.toggle('done',   i < cardIdx);
    });
  }

  /* ── Card stack ──
     Cards are rendered back-to-front in the DOM so the FIRST task
     (index cardIdx) is the last child = visually on top.
     Drag listeners attach only to the top card.
     Global mouse/touch handlers are added ONCE to the document,
     not per-card, to avoid listener accumulation.
  ── */

  // Single set of drag-state vars — one active card at a time
  let drag = { active: false, card: null, sx: 0, cx: 0 };

  function onDragMove(clientX) {
    if (!drag.active || !drag.card) return;
    drag.cx = clientX - drag.sx;
    drag.card.style.transform = `translateX(${drag.cx}px) rotate(${drag.cx * 0.07}deg)`;
    drag.card.classList.toggle('tilt-left',  drag.cx < -30);
    drag.card.classList.toggle('tilt-right', drag.cx >  30);
    labelLow.classList.toggle('lit',  drag.cx < -50);
    labelHigh.classList.toggle('lit', drag.cx >  50);
  }

  function onDragEnd() {
    if (!drag.active) return;
    drag.active = false;
    const card = drag.card;
    drag.card = null;
    if (card) {
      card.classList.remove('is-dragging', 'tilt-left', 'tilt-right');
    }
    labelLow.classList.remove('lit');
    labelHigh.classList.remove('lit');

    const cx = drag.cx;
    drag.cx = 0;

    if      (cx < -65) assignPriority('low',  card);
    else if (cx >  65) assignPriority('high', card);
    else if (card) {
      card.style.transition = 'transform .3s cubic-bezier(.34,1.56,.64,1)';
      card.style.transform  = 'none';
      setTimeout(() => { if (card) card.style.transition = ''; }, 320);
    }
  }

  // Global listeners added once
  document.addEventListener('mousemove', e => onDragMove(e.clientX));
  document.addEventListener('mouseup',   onDragEnd);
  document.addEventListener('touchmove', e => { if (drag.active) onDragMove(e.touches[0].clientX); }, { passive: true });
  document.addEventListener('touchend',  onDragEnd);

  function buildStack() {
    cardStack.innerHTML = '';
    // Render back cards first (they sit behind), then the top card last
    // so it's last-child in DOM = rendered on top by z-index
    const slice = dumped.slice(cardIdx, cardIdx + 3);
    // slice[0] = current top card — render it LAST
    // slice[2] = deepest back card — render it FIRST
    for (let i = slice.length - 1; i >= 0; i--) {
      const isTop = (i === 0);
      cardStack.appendChild(makeCard(slice[i], isTop));
    }
  }

  function makeCard(task, isTop) {
    const card = document.createElement('div');
    card.className = 'pyd-prio-card';
    card.dataset.taskId = task.id;
    card.innerHTML = `
      <p class="pyd-card-name">${escHtml(task.name)}</p>
      <p class="pyd-card-hint">swipe left = Low &nbsp;·&nbsp; right = High &nbsp;·&nbsp; or tap below</p>`;

    if (!isTop) return card;

    // Attach drag start to top card only
    card.addEventListener('mousedown', e => {
      drag.active = true;
      drag.card   = card;
      drag.sx     = e.clientX;
      drag.cx     = 0;
      card.classList.add('is-dragging');
      e.preventDefault();
    });
    card.addEventListener('touchstart', e => {
      drag.active = true;
      drag.card   = card;
      drag.sx     = e.touches[0].clientX;
      drag.cx     = 0;
      card.classList.add('is-dragging');
    }, { passive: true });

    return card;
  }

  function assignPriority(priority, cardEl) {
    const task = dumped[cardIdx];
    if (!task) return;
    prioritised.push({ ...task, priority });

    const exitCls = priority === 'high' ? 'pyd-exit-right' : 'pyd-exit-left';
    if (cardEl) {
      cardEl.style.transition = 'none'; // kill snap-back if mid-transition
      cardEl.classList.add(exitCls);
      cardEl.addEventListener('animationend', () => cardEl.remove(), { once: true });
    }

    cardIdx++;

    if (cardIdx >= dumped.length) {
      setTimeout(showCommit, 380);
    } else {
      updateStep();
      // Small delay so exit animation is visible, then rebuild
      setTimeout(() => {
        // Remove all cards that aren't animating out
        cardStack.querySelectorAll(`.pyd-prio-card:not(.pyd-exit-left):not(.pyd-exit-right)`).forEach(c => c.remove());
        buildStack();
      }, 160);
    }
  }

  /* Tap-to-assign — top card is always last-child */
  document.querySelectorAll('.pyd-prio-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      // top card = last child in the stack (rendered last = visually on top)
      const topCard = cardStack.querySelector('.pyd-prio-card:last-child');
      if (topCard) assignPriority(btn.dataset.prio, topCard);
    });
  });

  /* ── Commit screen ── */
  function showCommit() {
    const highN = prioritised.filter(t => t.priority === 'high').length;
    const potXP = prioritised.reduce((s, t) => s + xpFor(t.priority), 0);

    document.getElementById('pyd-commit-stats').innerHTML = `
      <div class="pyd-commit-stat"><span class="pyd-cstat-num">${prioritised.length}</span><span class="pyd-cstat-lbl">tasks</span></div>
      ${highN ? `<div class="pyd-commit-stat"><span class="pyd-cstat-num">${highN}</span><span class="pyd-cstat-lbl">high priority</span></div>` : ''}
      <div class="pyd-commit-stat"><span class="pyd-cstat-num">${potXP}</span><span class="pyd-cstat-lbl">potential XP</span></div>`;

    document.getElementById('pyd-planning-xp').innerHTML = `
      <svg width="14" height="14" viewBox="0 0 14 14" fill="none"><polygon points="7,1 9,5 13,5.5 10,8.5 11,13 7,10.5 3,13 4,8.5 1,5.5 5,5" fill="var(--accent)"/></svg>
      +${PLANNING_XP} XP for planning your day`;

    showScreen('commit');
  }

  /* ── Start my day — with double-entry protection ── */
  let pydSaving = false;

  document.getElementById('pyd-start-btn').addEventListener('click', async (e) => {
    if (pydSaving) return;  // prevent double-tap
    pydSaving = true;
    const startBtn = e.currentTarget;
    startBtn.disabled = true;
    // Pre-mark as done BEFORE the async loop so refresh/double-load can't re-trigger
    localStorage.setItem(PYD_DONE_KEY(), '1');
    try {
      // Use default area from saved prefs if available
      let defaultArea = 'client';
      try { const p = JSON.parse(localStorage.getItem('fb_area_prefs')); if (p && p.defaultArea) defaultArea = p.defaultArea; } catch {}
      for (const t of prioritised) {
        await addTask(t.name, t.priority, defaultArea, 'today', '', []);
      }
      totalXP += PLANNING_XP;
      await saveMeta();
      closePYD(true);
      showToast({ type: 'success', message: `Day planned! +${PLANNING_XP} XP earned`, duration: 3500 });
      setTimeout(() => showXPPop(PLANNING_XP, window.innerWidth / 2 - 30, window.innerHeight / 2 - 80), 600);
    } finally {
      pydSaving = false;
      startBtn.disabled = false;
    }
  });

  document.getElementById('pyd-edit-plan-btn').addEventListener('click', () => showScreen('dump'));

  /* ── Auto-show & trigger ── */
  function shouldShow() {
    const h = new Date().getHours();
    return h >= 5 && h < 12
      && !localStorage.getItem(PYD_DONE_KEY())
      && !tasks.filter(t => t.date === todayStr()).length;
  }

  window.openPlanYourDay = openPYD;

  // Inject "Plan your day" button into Today empty state
  const todayEmpty = document.getElementById('today-empty');
  if (todayEmpty) {
    const btn = document.createElement('button');
    btn.className = 'pyd-trigger-btn';
    btn.innerHTML = `<svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M8 2C8 2 11 5 11 7C11 8.7 9.65 10 8 10C6.35 10 5 8.7 5 7C5 5.8 5.7 4.7 6.6 3.9C6.6 5.1 7.3 5.6 8 5.6C8 4 8 2 8 2Z" fill="currentColor" opacity=".85"/></svg>Plan your day`;
    btn.addEventListener('click', openPYD);
    todayEmpty.appendChild(btn);
  }

  setTimeout(() => { if (shouldShow()) openPYD(); }, 2000);

})(); // end PlanYourDay IIFE

